values ('ap_chemistry', 6, '6.1', array['6.1', '6.2', '6.6', '6.7']::text[], 'vocabulary', 'Endothermic process', 'A process in which the energy of the system increases because the system gains energy from the surroundings as heat transfer to, or work done on, the system.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-002; ced=6.1.A.3 "increases (endothermic reaction)"')
