insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.1', array['6.1', '6.2', '6.6', '6.7']::text[], 'vocabulary', 'Exothermic process', 'A process in which the energy of the system decreases because the system loses energy to the surroundings as heat transfer from, or work done by, the system.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-001; ced=6.1.A.3 "the energy of the system either decreases (exothermic reaction)"')
