insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.1', array['6.1']::text[], 'convention', 'Solution formation can be exothermic or endothermic', 'Dissolving is exothermic or endothermic depending on the relative strengths of the intermolecular/interparticle interactions before and after dissolution.', '[]'::jsonb, NULL, 'Justify the claim by comparing interaction strengths before and after dissolving, not just by stating the temperature change.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-003; ced=6.1.A.4 "depending on the relative strengths of intermolecular/interparticle interactions"')
