insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.1', array['6.1', '6.4']::text[], 'list_sequence', 'Ways a chemical system changes its energy', 'The three main processes by which chemical systems change their energy (also the processes named as endothermic/exothermic examples).', '[{"label": "Heating/cooling", "meaning": "Heating raises the system''s energy; cooling lowers it."}, {"label": "Phase transitions", "meaning": "Melting and boiling raise the system''s energy; freezing and condensing lower it."}, {"label": "Chemical reactions", "meaning": "The system''s energy decreases (exothermic) or increases (endothermic)."}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-004; ced=6.4.A.6 "heating/cooling, phase transitions, and chemical reactions"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.2', array['6.2']::text[], 'diagram', 'Energy diagram for a physical or chemical process', 'A diagram that shows whether a process is endothermic or exothermic by comparing the energy of the starting and ending states.', '[{"label": "Energy axis", "meaning": "The vertical axis, labelled with energy and units."}, {"label": "Reactants (initial state) level", "meaning": "Energy of the system before the process."}, {"label": "Products (final state) level", "meaning": "Energy of the system after the process."}, {"label": "Direction of change", "meaning": "Products lower than reactants means exothermic; products higher means endothermic."}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-005; ced=6.2.A.1 "energy diagram that shows the endothermic or exothermic nature of that process"')
