values ('ap_chemistry', 6, '6.3', array['6.3', '6.4']::text[], 'vocabulary', 'Heat transfer (heat exchange)', 'The transfer of energy that results from collisions between particles in thermal contact, also called "transfer of energy as heat."', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-006; ced=6.3.A.2 "Collisions between particles in thermal contact can result in the transfer of energy"')
