insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.3', array['6.3', '6.6']::text[], 'vocabulary', 'Thermal equilibrium', 'The state reached through continued particle collisions in which two bodies have the same average kinetic energy and therefore the same temperature.', '[]'::jsonb, NULL, 'The warmer body''s particles have greater average kinetic energy before equilibrium; explain in terms of particle collisions and average kinetic energy.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-007; ced=6.3.A.3 "the average kinetic energy of both bodies is the same, and hence, their temperatures are the same"')
