insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.4', array['6.4']::text[], 'convention', 'Equal heat does not give equal temperature change', 'The same amount of thermal energy transferred to equal masses of substances with different specific heat capacities produces different temperature changes.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-011; ced=6.4.A.3 "will not produce the same temperature change in equal masses of matter with differing specific heat capacities"')
