values ('ap_chemistry', 6, '6.4', array['6.4', '6.9']::text[], 'vocabulary', 'First law of thermodynamics', 'Energy is conserved in chemical and physical processes.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-010; ced=6.4.A.2 "energy is conserved in chemical and physical processes"')
