values ('ap_chemistry', 6, '6.4', array['6.4']::text[], 'formula', 'Heat transfer equation', 'q = mc\Delta T', '[]'::jsonb, NULL, 'Use the mass of the whole substance whose temperature changes (e.g., total solution mass, not just the solute mass), and attend to significant figures.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-008; ced=6.4.A.1 "EQN: q = mcΔT"')
