insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.4', array['6.4', '6.1']::text[], 'convention', 'Reading dissolution calorimetry temperature changes', 'If the mixture''s temperature increases, the dissolution is exothermic (energy released); if it decreases, the dissolution is endothermic (energy absorbed).', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-012; ced=6.4.A.7 "If the temperature of the mixture increases, thermal energy is released by the dissolution process (exothermic)"')
