insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.4', array['6.4']::text[], 'vocabulary', 'Specific heat capacity vs. molar heat capacity', 'Both are heat capacities used in energy calculations; specific heat capacity is per mass of substance (c in q = mcΔT) and molar heat capacity is per mole.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-009; ced=6.4.A.5 "specific heat capacity of a substance and the molar heat capacity are both used in energy calculations"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.5', array['6.5']::text[], 'convention', 'Complementary phase changes have opposite enthalpies', 'The energy absorbed in one phase change equals the energy released in the reverse change, so molar enthalpy of condensation is the negative of molar enthalpy of vaporization (and freezing is the negative of fusion).', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-015; ced=6.5.A.2 "molar enthalpy of condensation of a substance is equal to the negative of its molar enthalpy of vaporization"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.5', array['6.5', '6.6']::text[], 'formula', 'Heat from moles and molar enthalpy', 'q = n\,\Delta H_{\text{molar}}', '[]'::jsonb, NULL, 'Sign matters: q is positive when energy is absorbed (melting, boiling, endothermic reaction) and negative when released.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-013; ced=6.5.A / 6.6.A "amount of the substance in moles and the molar enthalpy"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.5', array['6.5']::text[], 'convention', 'Phase changes: energy direction and constant temperature', 'Melting and boiling absorb energy (system energy increases), freezing and condensing release energy, and a pure substance''s temperature stays constant during a phase change.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-014; ced=6.5.A.1 "The temperature of a pure substance remains constant during a phase change"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.6', array['6.6', '6.7', '6.8', '6.9']::text[], 'convention', 'Sign of enthalpy change of reaction', 'A negative ΔH means heat is released by the reaction (exothermic); a positive ΔH means heat is absorbed (endothermic), at constant pressure.', '[]'::jsonb, NULL, 'A measured temperature increase in the surroundings means the reaction is exothermic, so ΔH must be reported as negative.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-016; ced=6.6.A.1 "released (for negative values) or absorbed (for positive values)"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.7', array['6.7']::text[], 'formula', 'Enthalpy of reaction from average bond energies', '\Delta H_{\text{reaction}} \approx \Sigma(\text{bond energies of bonds broken}) - \Sigma(\text{bond energies of bonds formed})', '[]'::jsonb, NULL, 'Count every bond broken in all reactant molecules and every bond formed in all product molecules, using the balanced equation''s coefficients. Energy released greater than energy required means exothermic.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-018; ced=6.7.A.2 "adding up the average bond energies of all the bonds in the reactant molecules"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.8', array['6.8']::text[], 'formula', 'Standard enthalpy of reaction from enthalpies of formation', '\Delta H^{\circ}_{\text{reaction}} = \Sigma \Delta H_f^{\circ}{}_{\text{products}} - \Sigma \Delta H_f^{\circ}{}_{\text{reactants}}', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-019; ced=6.8.A.1 "EQN: ΔH°reaction = ΣΔHf °products − ΣΔHf °reactants"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.9', array['6.9']::text[], 'convention', 'Enthalpy of an overall process equals the sum of its steps', 'At constant pressure, the enthalpy change of the overall process equals the sum of the enthalpy changes of the individual steps because total energy is conserved.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-021; ced=6.9.B.1 "the enthalpy change of the overall process is equal to the sum of the enthalpy changes of the individual steps"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 6, '6.9', array['6.9']::text[], 'list_sequence', 'Essential principles of Hess''s law', 'Three rules for manipulating reactions and their enthalpy changes to obtain an overall reaction.', '[{"label": "Reverse a reaction", "meaning": "ΔH keeps the same magnitude but its sign is reversed."}, {"label": "Multiply a reaction by a factor c", "meaning": "ΔH is multiplied by the same factor c."}, {"label": "Add reactions to get an overall reaction", "meaning": "The individual ΔH values are added to give the net ΔH of the overall reaction."}]'::jsonb, NULL, 'Check that the manipulated equations actually sum to the target overall equation before adding the ΔH values.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u6-r1-020; ced=6.9.B.2 "essential principles of Hess''s law"')
